<?php
class PlanillaPagoModel{private $db;function __construct(PDO $db){$this->db=$db;}function datos(int $id):array{$q=$this->db->prepare('SELECT * FROM periodos_pago WHERE id_periodo_pago=?');$q->execute([$id]);$periodo=$q->fetch();if(!$periodo)throw new InvalidArgumentException('Período no encontrado.');$q=$this->db->prepare("SELECT pd.*,CONCAT(p.apellidos,', ',p.nombres) trabajador FROM planilla_detalles pd JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo JOIN personas p ON p.id_persona=v.id_persona WHERE pd.id_periodo_pago=? ORDER BY p.apellidos,p.nombres");$q->execute([$id]);$detalles=$q->fetchAll();$q=$this->db->prepare("SELECT pp.*,CONCAT(p.apellidos,', ',p.nombres) trabajador,COALESCE(NULLIF(CONCAT(COALESCE(pr.apellidos,''),', ',COALESCE(pr.nombres,'')),', '),u.usuario,'Usuario') responsable FROM pagos_planilla pp JOIN planilla_detalles pd ON pd.id_planilla_detalle=pp.id_planilla_detalle JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo JOIN personas p ON p.id_persona=v.id_persona LEFT JOIN usuarios u ON u.id_usuario=pp.pagado_por LEFT JOIN personas pr ON pr.id_persona=u.id_persona WHERE pd.id_periodo_pago=? ORDER BY pp.pagado_en DESC,pp.id_pago_planilla DESC");$q->execute([$id]);$pagos=$q->fetchAll();return compact('periodo','detalles','pagos');}function registrar(array $d,int $usuario):int{$detalle=(int)($d['id_planilla_detalle']??0);$importe=round((float)($d['importe']??0),2);$medio=$d['medio_pago']??'';if(!$detalle||$importe<=0||!in_array($medio,['EFECTIVO','TRANSFERENCIA','DEPOSITO','OTRO'],true))throw new InvalidArgumentException('Complete correctamente el pago.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT pd.*,pp.estado periodo_estado FROM planilla_detalles pd JOIN periodos_pago pp ON pp.id_periodo_pago=pd.id_periodo_pago WHERE pd.id_planilla_detalle=? FOR UPDATE");$q->execute([$detalle]);$pd=$q->fetch();if(!$pd||!in_array($pd['periodo_estado'],['CERRADO','PAGADO'],true))throw new RuntimeException('La planilla debe estar cerrada para registrar pagos.');if($importe>(float)$pd['saldo_pendiente'])throw new RuntimeException('El importe supera el saldo pendiente.');$this->db->prepare("INSERT INTO pagos_planilla(id_planilla_detalle,importe,medio_pago,referencia,observacion,pagado_por,estado) VALUES(?,?,?,?,?,?,'REGISTRADO')")->execute([$detalle,$importe,$medio,trim($d['referencia']??'')?:null,trim($d['observacion']??'')?:null,$usuario]);$pagado=round((float)$pd['monto_pagado']+$importe,2);$saldo=max(0,round((float)$pd['monto_pagar']-$pagado,2));$this->db->prepare('UPDATE planilla_detalles SET monto_pagado=?,saldo_pendiente=?,estado=? WHERE id_planilla_detalle=?')->execute([$pagado,$saldo,$saldo<=0?'PAGADO':'PARCIAL',$detalle]);$this->actualizarPeriodo((int)$pd['id_periodo_pago']);$this->db->commit();return(int)$pd['id_periodo_pago'];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}function anular(int $id,string $motivo,int $usuario):int{$motivo=trim($motivo);if(!$id||strlen($motivo)<3)throw new InvalidArgumentException('Indique el motivo de anulación.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT pp.*,pd.id_periodo_pago,pd.monto_pagar,pd.monto_pagado FROM pagos_planilla pp JOIN planilla_detalles pd ON pd.id_planilla_detalle=pp.id_planilla_detalle WHERE pp.id_pago_planilla=? FOR UPDATE");$q->execute([$id]);$p=$q->fetch();if(!$p||$p['estado']!=='REGISTRADO')throw new RuntimeException('El pago no puede anularse.');$this->db->prepare("UPDATE pagos_planilla SET estado='ANULADO',anulado_por=?,anulado_en=NOW(),motivo_anulacion=? WHERE id_pago_planilla=?")->execute([$usuario,$motivo,$id]);$pagado=max(0,round((float)$p['monto_pagado']-(float)$p['importe'],2));$saldo=max(0,round((float)$p['monto_pagar']-$pagado,2));$estado=$pagado<=0?'CERRADO':($saldo<=0?'PAGADO':'PARCIAL');$this->db->prepare('UPDATE planilla_detalles SET monto_pagado=?,saldo_pendiente=?,estado=? WHERE id_planilla_detalle=?')->execute([$pagado,$saldo,$estado,$p['id_planilla_detalle']]);$this->db->prepare("UPDATE periodos_pago SET estado='CERRADO' WHERE id_periodo_pago=?")->execute([$p['id_periodo_pago']]);$this->db->commit();return(int)$p['id_periodo_pago'];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}private function actualizarPeriodo(int $id):void{$q=$this->db->prepare('SELECT COUNT(*) FROM planilla_detalles WHERE id_periodo_pago=? AND saldo_pendiente>0');$q->execute([$id]);if((int)$q->fetchColumn()===0)$this->db->prepare("UPDATE periodos_pago SET estado='PAGADO' WHERE id_periodo_pago=?")->execute([$id]);else $this->db->prepare("UPDATE periodos_pago SET estado='CERRADO' WHERE id_periodo_pago=?")->execute([$id]);}}
